package com.nigson.commerce.order;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.commerce.pricing.*;
import com.nigson.commerce.inventory.StockLedger;
import com.nigson.commerce.cart.CartCheckout;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
import tools.jackson.databind.JsonNode;
/** Atomic T1 and immutable commercial reads. Provider work belongs after commit. */
public final class JdbcOrderRepository implements OrderRepository {
 private final JdbcTemplate jdbc;private final CheckoutPricing pricing;private final CheckoutQuoteRepository quotes;private final StockLedger stock;private final CartCheckout carts;private final OrderPolicy policy;private final Clock clock;
 public JdbcOrderRepository(JdbcTemplate jdbc,CheckoutPricing pricing,CheckoutQuoteRepository quotes,StockLedger stock,CartCheckout carts,OrderPolicy policy,Clock clock){this.jdbc=jdbc;this.pricing=pricing;this.quotes=quotes;this.stock=stock;this.carts=carts;this.policy=policy;this.clock=clock;}
 private void transaction(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");}
 private static String money(BigDecimal value){return PricingValues.minor(PricingValues.decimal(value),2).toPlainString();}
 public void quoteOwner(ActorAssertion.Actor actor,UUID quote){quotes.requireReplay(actor,quote);}
 public UUID organization(UUID id){var rows=jdbc.queryForList("SELECT organization_id FROM commerce.sales_order WHERE id=?",id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return (UUID)rows.getFirst().get("organization_id");}
 public OrderValues.Order find(UUID id,boolean lock){if(lock)transaction();var rows=jdbc.queryForList("SELECT * FROM commerce.sales_order WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();var lines=jdbc.query("SELECT id,sku_id,sku_code,product_name,quantity,unit_amount,line_total FROM commerce.order_line WHERE order_id=? ORDER BY id LIMIT 101",(r,n)->new OrderValues.Line(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),PricingValues.decimal(r.getBigDecimal(5)),money(r.getBigDecimal(6)),money(r.getBigDecimal(7))),id);if(lines.isEmpty()||lines.size()>100)throw OrderValues.rule();var address=EventCodec.JSON.treeToValue(EventCodec.JSON.readTree(row.get("address_snapshot").toString()),OrderValues.Address.class);return new OrderValues.Order(id,row.get("order_number").toString(),row.get("status").toString(),row.get("payment_status").toString(),row.get("fulfillment_status").toString(),row.get("currency_code").toString(),new OrderValues.Totals(money((BigDecimal)row.get("subtotal")),money((BigDecimal)row.get("discount_total")),money((BigDecimal)row.get("tax_total")),money((BigDecimal)row.get("delivery_total")),money((BigDecimal)row.get("grand_total")),money((BigDecimal)row.get("refunded_total"))),List.copyOf(lines),address,((Number)row.get("version")).longValue(),((java.sql.Timestamp)row.get("created_at")).toInstant());}
 public OrderValues.Payment payment(UUID order){var rows=jdbc.query("SELECT id,state,checkout_url,reference,provider_mode FROM commerce.payment_attempt WHERE order_id=? ORDER BY created_at DESC,id DESC LIMIT 1",(r,n)->new OrderValues.Payment(r.getObject(1,UUID.class),r.getString(2),r.getString(5).equals("MOCK")&&r.getString(3)!=null&&r.getString(3).startsWith("http:")?null:r.getString(3),r.getString(4)),order);if(rows.size()!=1)throw OrderValues.rule();return rows.getFirst();}
 private void history(UUID id,String before,String after,String actor,String reason){jdbc.update("INSERT INTO commerce.order_status_history(id,created_by,order_id,previous_status,new_status,reason) VALUES (?,?,?,?,?,?)",EventCodec.uuid7(clock.instant()),actor,id,before,after,reason);}
 private Map<UUID,String> allocation(List<PricingValues.Line> lines){var locations=policy.locations();String marks=String.join(",",Collections.nCopies(locations.size(),"?"));jdbc.query("SELECT id FROM commerce.stock_location WHERE id IN ("+marks+") AND active ORDER BY id FOR SHARE",(r,n)->r.getObject(1,UUID.class),locations.toArray());var ids=new ArrayList<UUID>();for(var line:lines)ids.add(line.skuId());var args=new ArrayList<Object>(ids);args.addAll(locations);var balances=jdbc.queryForList("SELECT b.id,b.sku_id,b.location_id,b.on_hand-b.reserved-b.allocated AS available FROM commerce.inventory_balance b JOIN commerce.stock_location l ON l.id=b.location_id AND l.active WHERE b.sku_id IN ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") AND b.location_id IN ("+marks+") ORDER BY b.id LIMIT 1001 FOR UPDATE OF b",args.toArray());if(balances.size()>1000)throw OrderValues.rule();var selected=new LinkedHashMap<UUID,String>();for(var line:lines){UUID balance=null;for(UUID location:locations){for(var row:balances)if(row.get("sku_id").equals(line.skuId())&&row.get("location_id").equals(location)&&((BigDecimal)row.get("available")).compareTo(new BigDecimal(line.quantity()))>=0){balance=(UUID)row.get("id");break;}if(balance!=null)break;}if(balance==null)throw OrderValues.rule();selected.put(balance,line.quantity());}return selected;}
 public Created checkout(ActorAssertion.Actor actor,OrderValues.CheckoutInput input,UUID correlation){transaction();quoteOwner(actor,input.checkoutQuoteId());UUID cart=jdbc.queryForObject("SELECT cart_id FROM commerce.checkout_quote WHERE id=?",UUID.class,input.checkoutQuoteId());jdbc.query("SELECT id FROM commerce.cart WHERE id=? FOR UPDATE",(r,n)->r.getObject(1,UUID.class),cart);var existing=jdbc.queryForList("SELECT id,commercial_snapshot::text FROM commerce.sales_order WHERE cart_id=?",cart);if(!existing.isEmpty()){var previous=EventCodec.JSON.readTree(existing.getFirst().get("commercial_snapshot").toString());if(!previous.path("checkoutQuoteId").asString().equals(input.checkoutQuoteId().toString())||!previous.path("quoteHash").asString().equals(input.quoteHash()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);UUID id=(UUID)existing.getFirst().get("id");return new Created(new OrderValues.Checkout(find(id,false),payment(id)),false);}
  var snapshot=pricing.require(actor,input.checkoutQuoteId(),input.quoteHash());var q=snapshot.quote();var commercial=(tools.jackson.databind.node.ObjectNode)snapshot.commercial().deepCopy();String carrierMode=commercial.path("carrierMode").asString();policy.require(carrierMode);if(new BigDecimal(q.totals().grandTotal()).signum()<=0)throw OrderValues.rule();UUID market=ApiValues.uuid(commercial.path("marketId").asString()),carrier=ApiValues.uuid(commercial.path("carrierQuoteId").asString());UUID org=commercial.path("organizationId").isNull()?null:ApiValues.uuid(commercial.path("organizationId").asString());var assigned=allocation(q.lines());Instant now=clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS),expires=now.plusSeconds(policy.reservationSeconds());UUID id=EventCodec.uuid7(now),attempt=EventCodec.uuid7(now);String actorId=actor.party().toString();var address=snapshot.address();var frozenAddress=new OrderValues.Address("Checkout snapshot",address.recipient(),address.phone(),address.line1(),address.line2(),address.city(),address.region(),address.postalCode(),address.countryCode(),false);var carrierRows=jdbc.queryForList("SELECT version,package_snapshot::text,provider_snapshot::text FROM commerce.carrier_quote WHERE id=? AND status='QUOTED' FOR UPDATE",carrier);if(carrierRows.size()!=1||((Number)carrierRows.getFirst().get("version")).longValue()!=commercial.path("carrierQuoteVersion").asLong())throw new Problem.Failure(ProblemCode.CHECKOUT_REPRICE_REQUIRED);var frozenCarrier=new LinkedHashMap<String,Object>();frozenCarrier.put("schemaVersion",1);frozenCarrier.put("provider","FEDEX");frozenCarrier.put("mode",carrierMode);frozenCarrier.put("currency",q.currency());frozenCarrier.put("serviceCode",commercial.path("carrierService").asString());frozenCarrier.put("quoteId",carrier);frozenCarrier.put("quoteVersion",commercial.path("carrierQuoteVersion").asLong());frozenCarrier.put("addressHash",commercial.path("addressHash").asString());frozenCarrier.put("packageHash",commercial.path("packageHash").asString());frozenCarrier.put("packages",EventCodec.JSON.readTree(carrierRows.getFirst().get("package_snapshot").toString()));frozenCarrier.put("providerSnapshot",EventCodec.JSON.readTree(carrierRows.getFirst().get("provider_snapshot").toString()));commercial.put("checkoutQuoteId",input.checkoutQuoteId().toString());commercial.put("quoteHash",input.quoteHash());commercial.put("paymentMethod",input.paymentMethod());UUID accepted=null;if(!commercial.path("lines").isEmpty()&&commercial.path("lines").get(0).has("sourceQuoteRevisionId"))accepted=ApiValues.uuid(commercial.path("lines").get(0).path("sourceQuoteRevisionId").asString());
  jdbc.update("INSERT INTO commerce.sales_order(id,created_at,created_by,updated_by,order_number,party_id,organization_id,market_id,cart_id,status,payment_status,fulfillment_status,currency_code,subtotal,discount_total,tax_total,delivery_total,grand_total,address_snapshot,commercial_snapshot,reservation_expires_at,accepted_quote_revision_id,carrier_quote_id,carrier_snapshot) VALUES (?,?,?,?,?,?,?,?,?,'PENDING','UNPAID','UNFULFILLED','NGN',?,?,?,?,?,?::jsonb,?::jsonb,?,?,?,?::jsonb)",id,java.sql.Timestamp.from(now),actorId,actorId,"NIG_"+id.toString().replace("-",""),actor.party(),org,market,cart,new BigDecimal(q.totals().subtotal()),new BigDecimal(q.totals().discount()),new BigDecimal(q.totals().tax()),new BigDecimal(q.totals().delivery()),new BigDecimal(q.totals().grandTotal()),EventCodec.JSON.writeValueAsString(frozenAddress),EventCodec.JSON.writeValueAsString(commercial),java.sql.Timestamp.from(expires),accepted,carrier,EventCodec.JSON.writeValueAsString(frozenCarrier));
  for(JsonNode saved:commercial.path("lines")){var line=EventCodec.JSON.treeToValue(saved.get("line"),PricingValues.Line.class);var metadata=jdbc.queryForList("SELECT s.code,s.unit,p.name FROM commerce.sku s JOIN commerce.product p ON p.id=s.product_id WHERE s.id=?",line.skuId());if(metadata.size()!=1)throw OrderValues.rule();var m=metadata.getFirst();long revision=saved.has("priceBookRevision")?saved.get("priceBookRevision").asLong():saved.path("sourceQuoteRevision").asLong();jdbc.update("INSERT INTO commerce.order_line(id,created_by,order_id,sku_id,sku_code,product_name,unit,quantity,unit_amount,discount_amount,tax_amount,line_total,price_book_revision) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",EventCodec.uuid7(now),actorId,id,line.skuId(),m.get("code"),m.get("name"),m.get("unit"),new BigDecimal(line.quantity()),new BigDecimal(line.unitAmount()),new BigDecimal(saved.path("discount").asString()),new BigDecimal(saved.path("tax").asString()),new BigDecimal(line.lineTotal()),revision);}
  var components=new LinkedHashMap<String,String>();components.put("SUBTOTAL",q.totals().subtotal());components.put("DISCOUNT",q.totals().discount());components.put("TAX",q.totals().tax());components.put("DELIVERY",q.totals().delivery());for(var component:components.entrySet())jdbc.update("INSERT INTO commerce.order_total_component(id,created_by,order_id,component_type,amount,source_rule_id,source_revision,metadata) VALUES (?,?,?,?,?,?,?,?::jsonb)",EventCodec.uuid7(now),actorId,id,component.getKey(),new BigDecimal(component.getValue()),component.getKey().equals("DELIVERY")?carrier:null,component.getKey().equals("TAX")?Long.valueOf(commercial.path("marketRevision").asLong()):component.getKey().equals("DELIVERY")?Long.valueOf(commercial.path("carrierQuoteVersion").asLong()):null,EventCodec.JSON.writeValueAsString(Map.of("checkoutQuoteId",input.checkoutQuoteId(),"quoteHash",input.quoteHash())));
  jdbc.update("INSERT INTO commerce.payment_attempt(id,created_by,updated_by,order_id,provider,reference,merchant_account,expected_amount,currency_code,state,provider_mode) VALUES (?,?,?,?,'PAYSTACK',?,?,?,'NGN','CREATED',?)",attempt,actorId,actorId,id,"nigson-"+attempt.toString().replace("-",""),policy.merchantAccount(),new BigDecimal(q.totals().grandTotal()),policy.mode());history(id,null,"PENDING",actorId,"Current approved checkout snapshot");try{stock.reserve(id,assigned,expires,id,actorId,correlation);}catch(Problem.Failure failure){if(failure.getMessage().equals("INVENTORY_RULE_VIOLATION"))throw OrderValues.rule();throw failure;}carts.pending(actor.party(),cart,q.cartVersion(),q.id(),q.quoteHash(),id,correlation);jdbc.update("UPDATE commerce.carrier_quote SET status='CONSUMED',version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(now),actorId,carrier);return new Created(new OrderValues.Checkout(find(id,false),payment(id)),true);
 }
 public OrderValues.Page list(ActorAssertion.Actor actor,OrderValues.Query q,boolean staff){var args=new ArrayList<Object>();StringBuilder where=new StringBuilder(" WHERE 1=1");if(!staff){if(q.organizationId()==null){where.append(" AND ((o.party_id=? AND o.organization_id IS NULL) OR EXISTS(SELECT 1 FROM commerce.organization g JOIN commerce.organization_membership m ON m.organization_id=g.id WHERE g.id=o.organization_id AND g.status='ACTIVE' AND m.party_id=? AND m.status='ACTIVE'))");args.add(actor.party());args.add(actor.party());}else{where.append(" AND o.organization_id=?");args.add(q.organizationId());}}if(q.status()!=null){where.append(" AND o.status=?");args.add(q.status());}if(q.paymentStatus()!=null){where.append(" AND o.payment_status=?");args.add(q.paymentStatus());}if(q.from()!=null){where.append(" AND o.created_at>=?");args.add(java.sql.Timestamp.from(q.from()));}if(q.to()!=null){where.append(" AND o.created_at<?");args.add(java.sql.Timestamp.from(q.to()));}long total=jdbc.queryForObject("SELECT count(*) FROM commerce.sales_order o"+where,Long.class,args.toArray());String column=q.sort().startsWith("orderNumber")?"order_number":"created_at",direction=q.sort().endsWith("asc")?"ASC":"DESC";args.add(q.size());args.add((long)q.page()*q.size());var ids=jdbc.query("SELECT o.id FROM commerce.sales_order o"+where+" ORDER BY o."+column+" "+direction+",o.id "+direction+" LIMIT ? OFFSET ?",(r,n)->r.getObject(1,UUID.class),args.toArray());return new OrderValues.Page(ids.stream().map(id->find(id,false)).toList(),q.page(),q.size(),total,(total+q.size()-1)/q.size());}
 public OrderValues.Order processing(UUID id,long version,String actor,String reason){transaction();var before=find(id,true);if(before.version()!=version)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!before.status().equals("PAID")||!Set.of("PAID","PARTIALLY_REFUNDED").contains(before.paymentStatus())||!verified(id)||jdbc.queryForObject("SELECT hold_reason IS NOT NULL FROM commerce.sales_order WHERE id=?",Boolean.class,id))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(version==Long.MAX_VALUE)throw OrderValues.rule();jdbc.update("UPDATE commerce.sales_order SET status='PROCESSING',fulfillment_status='PROCESSING',version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(clock.instant()),actor,id);history(id,before.status(),"PROCESSING",actor,reason);return find(id,false);}
 private boolean verified(UUID id){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.sales_order o JOIN commerce.payment_attempt a ON a.order_id=o.id JOIN commerce.payment_transaction t ON t.attempt_id=a.id WHERE o.id=? AND a.provider='PAYSTACK' AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL AND a.expected_amount=o.grand_total AND t.settled_amount=a.expected_amount AND a.currency_code=o.currency_code AND t.currency_code=a.currency_code AND a.provider_mode=t.provider_mode AND a.provider_mode=CASE o.carrier_snapshot->>'mode' WHEN 'SANDBOX' THEN 'TEST' ELSE o.carrier_snapshot->>'mode' END AND t.provider_status='success')",Boolean.class,id));}
 public OrderValues.Order cancelled(UUID id,long version,String actor,String reason,UUID correlation){transaction();var before=find(id,true);if(before.version()!=version)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!before.status().equals("PENDING")||!Set.of("UNPAID","FAILED","PENDING").contains(before.paymentStatus()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(version==Long.MAX_VALUE)throw OrderValues.rule();if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.payment_attempt WHERE order_id=? AND (state NOT IN ('FAILED','CANCELLED') OR verified_at IS NULL)) OR EXISTS(SELECT 1 FROM commerce.payment_transaction t JOIN commerce.payment_attempt a ON a.id=t.attempt_id WHERE a.order_id=?)",Boolean.class,id,id)))throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);jdbc.update("UPDATE commerce.sales_order SET status='CANCELLED',payment_status=CASE WHEN payment_status='PENDING' THEN 'FAILED' ELSE payment_status END,fulfillment_status='CANCELLED',version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(clock.instant()),actor,id);history(id,before.status(),"CANCELLED",actor,reason);stock.release(id,id,actor,correlation);if(jdbc.queryForObject("SELECT cart_id FROM commerce.sales_order WHERE id=?",UUID.class,id)!=null)carts.expired(id,correlation);return find(id,false);}
 public OrderValues.Proof proof(OrderValues.ProofInput input){var rows=jdbc.queryForList("SELECT o.id,o.version,o.payment_status,o.hold_reason,l.quantity FROM commerce.order_line l JOIN commerce.sales_order o ON o.id=l.order_id JOIN commerce.sku s ON s.id=l.sku_id JOIN commerce.party p ON p.id=o.party_id WHERE l.id=? AND o.party_id=? AND s.product_id=? AND p.status='ACTIVE'",input.orderLineId(),input.partyId(),input.productId());if(rows.size()!=1)return new OrderValues.Proof(false,"NO_QUALIFYING_PURCHASE",0);var row=rows.getFirst();UUID order=(UUID)row.get("id");BigDecimal refunded=jdbc.queryForObject("SELECT coalesce(sum(l.quantity),0) FROM commerce.refund_line l JOIN commerce.refund r ON r.id=l.refund_id WHERE l.order_line_id=? AND r.order_id=? AND r.state='SUCCEEDED'",BigDecimal.class,input.orderLineId(),order);boolean eligible=Set.of("PAID","PARTIALLY_REFUNDED").contains(row.get("payment_status"))&&row.get("hold_reason")==null&&((BigDecimal)row.get("quantity")).compareTo(refunded)>0&&verified(order);return new OrderValues.Proof(eligible,eligible?"PURCHASE_VERIFIED":"NO_QUALIFYING_PURCHASE",((Number)row.get("version")).longValue());}
}
